@extends('layouts.app') @section('title','Dashboard') @section('header','Dashboard') @section('content')<div class="page-title"><div><h1>Estado general del sistema</h1><p>Resumen en tiempo real de la infraestructura IoT y condiciones ambientales.</p></div></div><div class="grid grid-4"><div class="card stat"><small>Bodegas activas</small><strong>{{ $stats['warehouses'] }}</strong><div class="meta">Ubicaciones configuradas</div></div><div class="card stat"><small>Dispositivos</small><strong>{{ $stats['devices'] }}</strong><div class="meta">Nodos registrados</div></div><div class="card stat"><small>En línea</small><strong>{{ $stats['online'] }}</strong><div class="meta">Con comunicación reciente</div></div><div class="card stat"><small>Alertas abiertas</small><strong>{{ $stats['open_alerts'] }}</strong><div class="meta">Requieren seguimiento</div></div></div><div class="grid grid-2" style="margin-top:18px"><div class="card"><div class="card-header"><h3>Últimas 24 horas @if($chartDevice) · {{ $chartDevice->name }} @endif</h3></div><div class="card-body"><div class="chart"><canvas id="mainChart" style="width:100%;height:100%"></canvas></div></div></div><div class="card"><div class="card-header"><h3>Alertas recientes</h3><a class="btn btn-secondary btn-sm" href="{{ route('alerts.index') }}">Ver todas</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Dispositivo</th><th>Alerta</th><th>Estado</th></tr></thead><tbody>@forelse($recentAlerts as $a)<tr><td>{{ $a->opened_at?->format('d/m H:i') }}</td><td>{{ $a->device->name }}</td><td>{{ $a->message }}</td><td><span class="badge {{ $a->status==='resolved'?'badge-success':($a->severity==='critical'?'badge-danger':'badge-warning') }}">{{ $a->status }}</span></td></tr>@empty<tr><td colspan="4" class="empty">Sin alertas registradas.</td></tr>@endforelse</tbody></table></div></div></div><div class="card" style="margin-top:18px"><div class="card-header"><h3>Dispositivos</h3>@if(auth()->user()->hasRole